#include <iostream>
#include <limits>
#include <optional>

std::optional<long long> checked_nonnegative_add(long long a, long long b) {
    if (a < 0 || b < 0 || b > std::numeric_limits<long long>::max() - a) {
        return std::nullopt;
    }
    return a + b;
}

int main() {
    const auto maximum = std::numeric_limits<long long>::max();
    const auto zero = checked_nonnegative_add(0, 0);
    const auto edge = checked_nonnegative_add(maximum, 0);
    if (!zero || *zero != 0 || !edge || *edge != maximum) return 1;
    if (checked_nonnegative_add(maximum, 1)) return 2;
    if (checked_nonnegative_add(-1, 0)) return 3;
    if (checked_nonnegative_add(0, -1)) return 4;
    std::cout << "boundary checks passed\n";
}

#include <iostream>
#include <limits>
#include <optional>

std::optional<long long> checked_nonnegative_add(long long a, long long b) {
    if (a < 0 || b < 0 || b > std::numeric_limits<long long>::max() - a) {
        return std::nullopt;
    }
    return a + b;
}


int main() {
    int checks = 0;
    for (long long a = 0; a <= 100; ++a) {
        for (long long b = 0; b <= 100; ++b) {
            const auto forward = checked_nonnegative_add(a, b);
            const auto reverse = checked_nonnegative_add(b, a);
            if (!forward || !reverse || *forward != *reverse) return 1;
            if (*forward - a != b) return 2;
            ++checks;
        }
    }
    std::cout << checks << " property cases passed\n";
}
